import { readFile } from "node:fs/promises";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import {
	loadTopology,
	releaseConsumers,
	workspaceById,
	workspaceByName,
} from "./repository-control-plane.mjs";
import { isString } from "./runtime-value-predicates.mjs";

const execFileAsync = promisify(execFile);
const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");

/**
 * Evaluate package-changeset coverage for a set of changed files.
 *
 * Pure repository logic: every input (which files changed, how changeset
 * files changed, and the base-revision manifest fallback) arrives as a
 * parameter so tests can drive it with ordinary filesystem fixtures without
 * invoking Git. The CLI wrapper gathers those inputs from Git.
 *
 * Returns `{ changedPackageCount }` on success and throws an Error with a
 * human-readable message when coverage is incomplete.
 */
export async function packageChangesetCoverage({
	root,
	topology,
	changedFiles,
	readManifestFromBase,
	changesetDiffLines,
}) {
	const releaseTriggerFiles = new Map(
		topology.release.triggers.map((trigger) => [
			trigger.path,
			workspaceById(topology, trigger.workspace).name,
		]),
	);
	const releaseBumps = new Set(["patch", "minor", "major"]);

	async function readPackageName(packagePath) {
		const manifestPath = `${packagePath}/package.json`;
		let contents;

		try {
			contents = await readFile(resolve(root, manifestPath), "utf8");
		} catch {
			contents = await readManifestFromBase(packagePath);
			if (contents === undefined) return undefined;
		}

		try {
			const packageJson = JSON.parse(contents);
			return isString(packageJson.name) ? packageJson.name : undefined;
		} catch {
			return undefined;
		}
	}

	const changedPackagePaths = new Set();
	for (const file of changedFiles) {
		const match = file.match(/^packages\/([^/]+)(?:\/|$)/);
		if (match) changedPackagePaths.add(`packages/${match[1]}`);
	}

	const changedPackages = new Map();
	for (const path of changedPackagePaths) {
		const packageName = await readPackageName(path);
		if (packageName) changedPackages.set(path, packageName);
	}
	for (const file of changedFiles) {
		const packageName = releaseTriggerFiles.get(file);
		if (packageName) changedPackages.set(file, packageName);
	}

	if (changedPackages.size === 0) {
		console.log("No workspace package changes require a package changeset.");
		return { changedPackageCount: 0 };
	}

	const changedChangesetFiles = changesetDiffLines.flatMap((line) => {
		const [status, sourcePath, destinationPath] = line.split("\t");
		if (status === "A" || status === "M") return [sourcePath];
		if (status.startsWith("R") && status !== "R100") {
			return [destinationPath];
		}
		return [];
	}).filter((file) => /^\.changeset\/[^/]+\.md$/.test(file));

	const changesetReleases = new Set();
	const emptyChangesetFiles = [];
	let changedChangesetCount = 0;
	for (const file of changedChangesetFiles) {
		let contents;
		try {
			contents = await readFile(resolve(root, file), "utf8");
		} catch {
			continue;
		}
		changedChangesetCount += 1;
		const fileReleases = new Set();
		const frontmatter = contents.match(/^---\s*\n([\s\S]*?)\n---/);
		if (frontmatter) {
			for (const line of frontmatter[1].split("\n")) {
				const match = line.match(
					/^\s*(?:"([^"]+)"|'([^']+)'|([@A-Za-z0-9._/-]+))\s*:\s*([A-Za-z]+)\s*$/,
				);
				if (!match) continue;
				const packageName = match[1] ?? match[2] ?? match[3];
				const bump = match[4];
				if (!releaseBumps.has(bump)) continue;
				fileReleases.add(packageName);
				changesetReleases.add(packageName);
			}
		}
		if (fileReleases.size === 0) emptyChangesetFiles.push(file);
	}

	if (changedChangesetCount === 0) {
		throw new Error(
			`Changed workspace packages need a changeset added or modified by this branch:\n${Array.from(changedPackages.entries(), ([path, packageName]) => `- ${path} -> ${packageName}`).join("\n")}`,
		);
	}

	if (emptyChangesetFiles.length > 0) {
		throw new Error(
			`Empty Changesets cannot accompany release-triggering changes:\n${emptyChangesetFiles.map((file) => `- ${file}`).join("\n")}\nRelease-triggering changes require non-empty bumps:\n${Array.from(changedPackages.entries(), ([path, packageName]) => `- ${path} -> ${packageName}`).join("\n")}`,
		);
	}

	const missing = [...changedPackages.entries()]
		.filter(([, packageName]) => !changesetReleases.has(packageName))
		.map(([path, packageName]) => `${path} -> ${packageName}`);

	if (missing.length > 0) {
		throw new Error(
			`Changed workspace packages need a changeset naming the same package:\n${missing.map((entry) => `- ${entry}`).join("\n")}`,
		);
	}

	function getTransitiveConsumers(packageName) {
		let workspace;
		try {
			workspace = workspaceByName(topology, packageName);
		} catch {
			return [];
		}
		return releaseConsumers(topology, workspace.id).map(
			(consumer) => workspaceById(topology, consumer).name,
		);
	}

	const cascadeRoots = topology.release.bundles.map(
		(bundle) => workspaceById(topology, bundle.workspace).name,
	);
	const incompleteCascades = cascadeRoots
		.filter((packageName) => changesetReleases.has(packageName))
		.map((packageName) => ({
			packageName,
			missing: getTransitiveConsumers(packageName).filter(
				(consumer) => !changesetReleases.has(consumer),
			),
		}))
		.filter(({ missing }) => missing.length > 0);

	if (incompleteCascades.length > 0) {
		throw new Error(
			`Bundled release cascades must include every transitive shipped consumer with at least a patch bump:\n${incompleteCascades
				.map(
					({ packageName, missing }) =>
						`- ${packageName} -> missing ${missing.join(", ")}`,
				)
				.join("\n")}`,
		);
	}

	const allowedReleases = new Set();
	for (const packageName of changedPackages.values()) {
		allowedReleases.add(packageName);
		for (const consumer of getTransitiveConsumers(packageName)) {
			allowedReleases.add(consumer);
		}
	}
	const unrelatedReleases = [...changesetReleases].filter(
		(packageName) => !allowedReleases.has(packageName),
	);
	if (unrelatedReleases.length > 0) {
		throw new Error(
			`Changesets must not couple unrelated package releases:\n${unrelatedReleases
				.map((packageName) => `- ${packageName}`)
				.join("\n")}`,
		);
	}

	console.log(
		`Package changeset coverage passed for ${changedPackages.size} workspace package(s).`,
	);
	return { changedPackageCount: changedPackages.size };
}

const isMain =
	process.argv[1] !== undefined &&
	import.meta.url === pathToFileURL(process.argv[1]).href;

if (isMain) {
	const sinceIndex = process.argv.indexOf("--since");
	const since =
		sinceIndex >= 0 ? process.argv[sinceIndex + 1] : "origin/main";

	if (!since) throw new Error("Missing value for --since");

	const topology = await loadTopology(root);
	const { stdout } = await execFileAsync(
		"git",
		["diff", "--name-only", "--diff-filter=ACMRD", `${since}...HEAD`],
		{ cwd: root },
	);
	const changedFiles = stdout.trim().split("\n").filter(Boolean);
	const readManifestFromBase = async (packagePath) => {
		try {
			const result = await execFileAsync(
				"git",
				["show", `${since}:${packagePath}/package.json`],
				{ cwd: root },
			);
			return result.stdout;
		} catch {
			return undefined;
		}
	};
	const { stdout: changesetDiff } = await execFileAsync(
		"git",
		[
			"diff",
			"--name-status",
			"--find-renames",
			`${since}...HEAD`,
			"--",
			".changeset",
		],
		{ cwd: root },
	);

	try {
		await packageChangesetCoverage({
			root,
			topology,
			changedFiles,
			readManifestFromBase,
			changesetDiffLines: changesetDiff.trim().split("\n").filter(Boolean),
		});
	} catch (error) {
		console.error(error.message);
		process.exit(1);
	}
}

import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import {
	packageChangesetCoverage,
} from "./check-package-changesets.mjs";
import { loadTopology } from "./repository-control-plane.mjs";

const fixtureDirectories = new Set<string>();
const repositoryRoot = resolve(dirname(new URL(import.meta.url).pathname), "..");
const topology = await loadTopology(repositoryRoot);

afterEach(async () => {
	await Promise.all(
		Array.from(fixtureDirectories, (directory) =>
			rm(directory, { recursive: true, force: true }),
		),
	);
	fixtureDirectories.clear();
});

async function writeFixtureFile(root: string, path: string, contents: string) {
	const target = join(root, path);
	await mkdir(dirname(target), { recursive: true });
	await writeFile(target, contents);
}

function changesetFrontmatter(
	releases: Record<string, "major" | "minor" | "patch">,
	summary: string,
): string {
	return `---\n${Object.entries(releases)
		.map(([packageName, bump]) => `"${packageName}": ${bump}`)
		.join("\n")}\n---\n\n${summary}\n`;
}

async function writeChangeset(
	root: string,
	packages: string[],
	bumps: Record<string, "major" | "minor" | "patch"> = {},
) {
	await writeFixtureFile(
		root,
		".changeset/new.md",
		changesetFrontmatter(
			Object.fromEntries(
				packages.map((packageName) => [
					packageName,
					bumps[packageName] ?? "patch",
				]),
			),
			"Runtime package release.",
		),
	);
}

async function createFixture(
	options: {
		existingChangeset?: boolean;
		packageName?: string;
		packagePath?: string;
	} = {},
) {
	const root = await mkdtemp(join(tmpdir(), "hevy-package-changesets-"));
	fixtureDirectories.add(root);
	const packageName = options.packageName ?? "@example/pkg";
	const packagePath = options.packagePath ?? "packages/example";

	// Base revision state, used for the deleted-manifest fallback.
	const base = new Map<string, string>();
	const put = async (path: string, contents: string) => {
		base.set(path, contents);
		await writeFixtureFile(root, path, contents);
	};

	await put(
		`${packagePath}/package.json`,
		JSON.stringify({ name: packageName }) + "\n",
	);
	await put(`${packagePath}/src/index.js`, 'export const value = "base";\n');
	await put(".changeset/README.md", "# Changesets\n");
	if (options.existingChangeset) {
		await put(
			".changeset/existing.md",
			'---\n"@example/pkg": patch\n---\n\nExisting release note.\n',
		);
	}

	return {
		root,
		packageName,
		packagePath,
		readManifestFromBase: async (changedPackagePath: string) =>
			base.get(`${changedPackagePath}/package.json`),
	};
}

async function runCheck(
	fixture: Awaited<ReturnType<typeof createFixture>>,
	options: {
		changedFiles?: string[];
		changesetDiffLines?: string[];
	} = {},
) {
	return packageChangesetCoverage({
		root: fixture.root,
		topology,
		changedFiles: options.changedFiles ?? [],
		changesetDiffLines: options.changesetDiffLines ?? [],
		readManifestFromBase: fixture.readManifestFromBase,
	});
}

describe("package changeset coverage", () => {
	it("does not let a base-branch changeset cover a PR package change", async () => {
		const fixture = await createFixture({ existingChangeset: true });
		await writeFixtureFile(
			fixture.root,
			"packages/example/src/index.js",
			'export const value = "changed";\n',
		);

		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/example/src/index.js"],
			}),
		).rejects.toThrow(
			"Changed workspace packages need a changeset added or modified by this branch",
		);
	});

	it("does not let a rename-only changeset cover a PR package change", async () => {
		const fixture = await createFixture({ existingChangeset: true });
		await writeFixtureFile(
			fixture.root,
			"packages/example/src/index.js",
			'export const value = "changed";\n',
		);
		await rm(join(fixture.root, ".changeset/existing.md"));
		await writeFixtureFile(
			fixture.root,
			".changeset/renamed.md",
			'---\n"@example/pkg": patch\n---\n\nExisting release note.\n',
		);

		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/example/src/index.js"],
				changesetDiffLines: [
					"R100\t.changeset/existing.md\t.changeset/renamed.md",
				],
			}),
		).rejects.toThrow(
			"Changed workspace packages need a changeset added or modified by this branch",
		);
	});

	it("rejects an empty changeset for a workspace package change", async () => {
		const fixture = await createFixture();
		await writeFixtureFile(
			fixture.root,
			"packages/example/src/index.js",
			'export const value = "changed";\n',
		);
		await writeFixtureFile(fixture.root, ".changeset/empty.md", "---\n---\n\nNo release.\n");

		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/example/src/index.js"],
				changesetDiffLines: ["A\t.changeset/empty.md"],
			}),
		).rejects.toThrow("Empty Changesets cannot accompany release-triggering changes");
		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/example/src/index.js"],
				changesetDiffLines: ["A\t.changeset/empty.md"],
			}),
		).rejects.toThrow(".changeset/empty.md");
	});

	it("rejects an empty changeset alongside a matching bump", async () => {
		const fixture = await createFixture();
		await writeFixtureFile(
			fixture.root,
			"packages/example/src/index.js",
			'export const value = "changed";\n',
		);
		await writeFixtureFile(
			fixture.root,
			".changeset/bump.md",
			'---\n"@example/pkg": patch\n---\n\nRelease change.\n',
		);
		await writeFixtureFile(fixture.root, ".changeset/empty.md", "---\n---\n\nNo release.\n");

		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/example/src/index.js"],
				changesetDiffLines: [
					"A\t.changeset/bump.md",
					"A\t.changeset/empty.md",
				],
			}),
		).rejects.toThrow("Empty Changesets cannot accompany release-triggering changes");
	});

	it("accepts an empty changeset for a root-level no-release change", async () => {
		const fixture = await createFixture();
		await writeFixtureFile(fixture.root, "CONTRIBUTING.md", "No release.\n");
		await writeFixtureFile(fixture.root, ".changeset/empty.md", "---\n---\n\nNo release.\n");

		await expect(
			runCheck(fixture, {
				changedFiles: ["CONTRIBUTING.md"],
				changesetDiffLines: ["A\t.changeset/empty.md"],
			}),
		).resolves.toEqual({ changedPackageCount: 0 });
	});

	it("requires a changeset for deletion-only package changes", async () => {
		const fixture = await createFixture();
		await rm(join(fixture.root, "packages/example/src/index.js"));

		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/example/src/index.js"],
			}),
		).rejects.toThrow("packages/example -> @example/pkg");
	});

	it("resolves a fully deleted package name from the base revision", async () => {
		const fixture = await createFixture();
		await rm(join(fixture.root, "packages/example"), {
			recursive: true,
		});

		await expect(
			runCheck(fixture, {
				changedFiles: [
					"packages/example/package.json",
					"packages/example/src/index.js",
				],
			}),
		).rejects.toThrow("packages/example -> @example/pkg");
	});

	it("accepts a matching changeset added by the branch", async () => {
		const fixture = await createFixture({ existingChangeset: true });
		await writeFixtureFile(
			fixture.root,
			"packages/example/src/index.js",
			'export const value = "changed";\n',
		);
		await writeFixtureFile(
			fixture.root,
			".changeset/new.md",
			'---\n"@example/pkg": patch\n---\n\nNew release note.\n',
		);

		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/example/src/index.js"],
				changesetDiffLines: ["A\t.changeset/new.md"],
			}),
		).resolves.toEqual({ changedPackageCount: 1 });
	});

	it("lists every missing transitive consumer for a client release", async () => {
		const fixture = await createFixture({
			packageName: "@hevy-mcp/hevy-client",
			packagePath: "packages/hevy-client",
		});
		await writeFixtureFile(
			fixture.root,
			"packages/hevy-client/src/index.js",
			'export const value = "changed";\n',
		);
		await writeChangeset(fixture.root, [
			"@hevy-mcp/hevy-client",
			"@hevy-mcp/operations",
			"@hevy-mcp/core",
			"hevy-mcp",
		]);

		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/hevy-client/src/index.js"],
				changesetDiffLines: ["A\t.changeset/new.md"],
			}),
		).rejects.toThrow("@hevy-mcp/worker");
		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/hevy-client/src/index.js"],
				changesetDiffLines: ["A\t.changeset/new.md"],
			}),
		).rejects.toThrow("@chrisdoc/hevy-cli");
	});

	it("accepts the complete client release cascade", async () => {
		const fixture = await createFixture({
			packageName: "@hevy-mcp/hevy-client",
			packagePath: "packages/hevy-client",
		});
		await writeFixtureFile(
			fixture.root,
			"packages/hevy-client/src/index.js",
			'export const value = "changed";\n',
		);
		await writeChangeset(fixture.root, [
			"@hevy-mcp/hevy-client",
			"@hevy-mcp/operations",
			"@hevy-mcp/core",
			"hevy-mcp",
			"@hevy-mcp/worker",
			"@chrisdoc/hevy-cli",
		]);

		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/hevy-client/src/index.js"],
				changesetDiffLines: ["A\t.changeset/new.md"],
			}),
		).resolves.toEqual({ changedPackageCount: 1 });
	});

	it("allows patch consumer bumps for a major client release", async () => {
		const fixture = await createFixture({
			packageName: "@hevy-mcp/hevy-client",
			packagePath: "packages/hevy-client",
		});
		await writeFixtureFile(
			fixture.root,
			"packages/hevy-client/src/index.js",
			'export const value = "changed";\n',
		);
		await writeChangeset(fixture.root, ["@hevy-mcp/hevy-client"], {
			"@hevy-mcp/hevy-client": "major",
			"@hevy-mcp/operations": "patch",
			"@hevy-mcp/core": "patch",
			"hevy-mcp": "patch",
			"@hevy-mcp/worker": "patch",
			"@chrisdoc/hevy-cli": "patch",
		});

		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/hevy-client/src/index.js"],
				changesetDiffLines: ["A\t.changeset/new.md"],
			}),
		).resolves.toEqual({ changedPackageCount: 1 });
	});

	it("lists missing shipped consumers for a core release", async () => {
		const fixture = await createFixture({
			packageName: "@hevy-mcp/core",
			packagePath: "packages/core",
		});
		await writeFixtureFile(
			fixture.root,
			"packages/core/src/index.js",
			'export const value = "changed";\n',
		);
		await writeChangeset(fixture.root, ["@hevy-mcp/core", "hevy-mcp"]);

		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/core/src/index.js"],
				changesetDiffLines: ["A\t.changeset/new.md"],
			}),
		).rejects.toThrow("@hevy-mcp/worker");
		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/core/src/index.js"],
				changesetDiffLines: ["A\t.changeset/new.md"],
			}),
		).rejects.toThrow("@chrisdoc/hevy-cli");
	});

	it("accepts the complete core release cascade", async () => {
		const fixture = await createFixture({
			packageName: "@hevy-mcp/core",
			packagePath: "packages/core",
		});
		await writeFixtureFile(
			fixture.root,
			"packages/core/src/index.js",
			'export const value = "changed";\n',
		);
		await writeChangeset(fixture.root, [
			"@hevy-mcp/core",
			"hevy-mcp",
			"@hevy-mcp/worker",
			"@chrisdoc/hevy-cli",
		]);

		await expect(
			runCheck(fixture, {
				changedFiles: ["packages/core/src/index.js"],
				changesetDiffLines: ["A\t.changeset/new.md"],
			}),
		).resolves.toEqual({ changedPackageCount: 1 });
	});

	it.each([
		["hevy-mcp", "packages/node"],
		["@hevy-mcp/worker", "packages/worker"],
		["@chrisdoc/hevy-cli", "packages/cli"],
	])("accepts an isolated %s release", async (packageName, packagePath) => {
		const fixture = await createFixture({ packageName, packagePath });
		await writeFixtureFile(
			fixture.root,
			`${packagePath}/src/index.js`,
			'export const value = "changed";\n',
		);
		await writeChangeset(fixture.root, [packageName]);

		await expect(
			runCheck(fixture, {
				changedFiles: [`${packagePath}/src/index.js`],
				changesetDiffLines: ["A\t.changeset/new.md"],
			}),
		).resolves.toEqual({ changedPackageCount: 1 });
	});

	it.each([
		["hevy-mcp", "packages/node", "@hevy-mcp/worker"],
		["@hevy-mcp/worker", "packages/worker", "hevy-mcp"],
		["@chrisdoc/hevy-cli", "packages/cli", "hevy-mcp"],
	])(
		"rejects %s changes coupled to an unrelated release",
		async (packageName, packagePath, unrelatedPackage) => {
			const fixture = await createFixture({ packageName, packagePath });
			await writeFixtureFile(
				fixture.root,
				`${packagePath}/src/index.js`,
				'export const value = "changed";\n',
			);
			await writeChangeset(fixture.root, [packageName, unrelatedPackage]);

			await expect(
				runCheck(fixture, {
					changedFiles: [`${packagePath}/src/index.js`],
					changesetDiffLines: ["A\t.changeset/new.md"],
				}),
			).rejects.toThrow(
				"Changesets must not couple unrelated package releases",
			);
			await expect(
				runCheck(fixture, {
					changedFiles: [`${packagePath}/src/index.js`],
					changesetDiffLines: ["A\t.changeset/new.md"],
				}),
			).rejects.toThrow(unrelatedPackage);
		},
	);

	it("requires a Worker release for production Worker config changes", async () => {
		const fixture = await createFixture();
		await writeFixtureFile(
			fixture.root,
			"cloudflare.config.ts",
			'export const workerName = "changed";\n',
		);
		await writeChangeset(fixture.root, []);

		await expect(
			runCheck(fixture, {
				changedFiles: ["cloudflare.config.ts"],
				changesetDiffLines: ["A\t.changeset/new.md"],
			}),
		).rejects.toThrow("cloudflare.config.ts -> @hevy-mcp/worker");
	});

	it("accepts a Worker release for production Worker config changes", async () => {
		const fixture = await createFixture();
		await writeFixtureFile(
			fixture.root,
			"cloudflare.config.ts",
			'export const workerName = "changed";\n',
		);
		await writeChangeset(fixture.root, ["@hevy-mcp/worker"]);

		await expect(
			runCheck(fixture, {
				changedFiles: ["cloudflare.config.ts"],
				changesetDiffLines: ["A\t.changeset/new.md"],
			}),
		).resolves.toEqual({ changedPackageCount: 1 });
	});
});

